3.  **Create the server file** (`server.js`):
    Create a file named `server.js` inside the backend folder and paste this code:

    ```javascript
    const express = require('express');
    const cors = require('cors');
    const bodyParser = require('body-parser');

    const app = express();
    const PORT = 5000;

    // Middleware
    app.use(cors()); // Allow React to talk to this server
    app.use(bodyParser.json());

    // Dummy Data (In-memory database)
    let tasks = [
        { id: 1, text: "Learn Node.js", completed: false },
        { id: 2, text: "Build a React App", completed: true }
    ];

    // 1. GET: Fetch all tasks
    app.get('/api/tasks', (req, res) => {
        res.json(tasks);
    });

    // 2. POST: Add a new task
    app.post('/api/tasks', (req, res) => {
        const { text } = req.body;
        if (!text) {
            return res.status(400).json({ error: "Text is required" });
        }

        const newTask = {
            id: tasks.length + 1,
            text: text,
            completed: false
        };

        tasks.push(newTask);
        res.json(newTask);
    });

    // Start Server
    app.listen(PORT, () => {
        console.log(`Server running on http://localhost:${PORT}`);
    });
